# ---------------- helpers ----------------
def load_settings():
    try:
        with open(SETTINGS_FILE, "r", encoding="utf-8") as f:
            d = json.load(f)
        out = dict(DEFAULTS)
        out.update(d)
        return out
    except Exception:
        return dict(DEFAULTS)


def save_settings(cfg):
    try:
        os.makedirs(SETTINGS_DIR, exist_ok=True)
        with open(SETTINGS_FILE, "w", encoding="utf-8") as f:
            json.dump(cfg, f)
    except Exception:
        pass


def is_admin():
    try:
        return ctypes.windll.shell32.IsUserAnAdmin() != 0
    except Exception:
        return False


def run(args, timeout=120):
    """Run a command, return (returncode, output). Never raises."""
    try:
        r = subprocess.run(args, shell=isinstance(args, str), capture_output=True, text=True,
                           errors="replace", creationflags=NO_WINDOW, timeout=timeout)
        return r.returncode, ((r.stdout or "") + (r.stderr or "")).strip()
    except Exception as e:
        return 1, str(e)


def ps(script, timeout=120):
    return run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", script], timeout)


def reg_set(path, name, kind, value):
    return run(["reg", "add", path, "/v", name, "/t", kind, "/d", str(value), "/f"])[0] == 0


def reg_del(path, name):
    return run(["reg", "delete", path, "/v", name, "/f"])[0] == 0


def fmt_mb(b):
    return f"{b / 1048576:.0f} MB"


def wipe(path):
    """Delete contents of a folder (not the folder). Returns bytes freed."""
    freed = 0
    if not path or not os.path.isdir(path):
        return 0
    for root, dirs, files in os.walk(path, topdown=False):
        for f in files:
            fp = os.path.join(root, f)
            try:
                s = os.path.getsize(fp)
                os.remove(fp)
                freed += s
            except Exception:
                pass
        for d in dirs:
            try:
                os.rmdir(os.path.join(root, d))
            except Exception:
                pass
    return freed


def env(name, default=""):
    return os.environ.get(name, default)


# ---------------- GameLoop discovery ----------------
def gameloop_roots():
    roots = []
    for base in (env("ProgramFiles"), env("ProgramFiles(x86)")):
        if base:
            roots.append(os.path.join(base, "TxGameAssistant"))
    for d in "CDEFGH":
        roots += [f"{d}:\\Program Files\\TxGameAssistant", f"{d}:\\Program Files (x86)\\TxGameAssistant",
                  f"{d}:\\TxGameAssistant", f"{d}:\\Games\\TxGameAssistant"]
    seen, out = set(), []
    for r in roots:
        if r.lower() not in seen and os.path.isdir(r):
            seen.add(r.lower())
            out.append(r)
    return out


def find_files(names, depth=4):
    names = {n.lower() for n in names}
    found = set()
    for p in psutil.process_iter(["name", "exe"]):
        try:
            if (p.info["name"] or "").lower() in names and p.info["exe"]:
                found.add(p.info["exe"])
        except Exception:
            pass
    for root in gameloop_roots():
        base_depth = root.count(os.sep)
        for cur, dirs, files in os.walk(root):
            if cur.count(os.sep) - base_depth >= depth:
                dirs[:] = []
            for f in files:
                if f.lower() in names:
                    found.add(os.path.join(cur, f))
    return found


def game_running():
    try:
        for p in psutil.process_iter(["name"]):
            if (p.info["name"] or "").lower() in GAME_MAIN:
                return True
    except Exception:
        pass
    return False


# ---------------- system actions ----------------
def set_high_perf():
    rc, _ = run(["powercfg", "/setactive", "8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c"])
    if rc != 0:
        run(["powercfg", "/duplicatescheme", "8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c"])
        rc, _ = run(["powercfg", "/setactive", "8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c"])
    return rc == 0


def set_timer(on):
    try:
        ctypes.windll.ntdll.NtSetTimerResolution(5000, bool(on), ctypes.byref(ctypes.c_ulong()))
        return True
    except Exception:
        return False


def clean_ram():
    k32, psapi = ctypes.windll.kernel32, ctypes.windll.psapi
    k32.OpenProcess.restype = ctypes.c_void_p
    k32.OpenProcess.argtypes = [ctypes.c_ulong, ctypes.c_int, ctypes.c_ulong]
    psapi.EmptyWorkingSet.argtypes = [ctypes.c_void_p]
    k32.CloseHandle.argtypes = [ctypes.c_void_p]
    before = psutil.virtual_memory().available
    for p in psutil.process_iter(["pid", "name"]):
        if (p.info["name"] or "").lower() in GAME_PROCS or p.info["pid"] in (0, 4):
            continue
        try:
            h = k32.OpenProcess(0x0500, False, p.info["pid"])
            if h:
                psapi.EmptyWorkingSet(h)
                k32.CloseHandle(h)
        except Exception:
            pass
    return max(psutil.virtual_memory().available - before, 0)


def clean_temp():
    paths = [env("TEMP"), os.path.join(env("SystemRoot", r"C:\Windows"), "Temp"),
             os.path.join(env("LOCALAPPDATA"), "CrashDumps"),
             os.path.join(env("LOCALAPPDATA"), "Microsoft", "Windows", "INetCache"),
             os.path.join(env("LOCALAPPDATA"), "Microsoft", "Windows", "WER"),
             os.path.join(env("ProgramData"), "Microsoft", "Windows", "WER", "ReportArchive"),
             os.path.join(env("ProgramData"), "Microsoft", "Windows", "WER", "ReportQueue"),
             os.path.join(env("SystemRoot", r"C:\Windows"), "Minidump")]
    freed = sum(wipe(p) for p in paths)
    try:
        dmp = os.path.join(env("SystemRoot", r"C:\Windows"), "MEMORY.DMP")
        if os.path.isfile(dmp):
            freed += os.path.getsize(dmp)
            os.remove(dmp)
    except Exception:
        pass
    return freed


def clean_wupdate():
    for s in ("wuauserv", "bits", "dosvc"):
        run(["net", "stop", s])
    root = env("SystemRoot", r"C:\Windows")
    freed = wipe(os.path.join(root, "SoftwareDistribution", "Download"))
    freed += wipe(os.path.join(root, "ServiceProfiles", "NetworkService", "AppData", "Local",
                               "Microsoft", "Windows", "DeliveryOptimization", "Cache"))
    for s in ("bits", "wuauserv", "dosvc"):
        run(["net", "start", s])
    return freed


def clean_browsers():
    for exe in ("chrome.exe", "msedge.exe", "brave.exe", "firefox.exe", "opera.exe"):
        run(["taskkill", "/f", "/im", exe])
    time.sleep(1)
    lad = env("LOCALAPPDATA")
    freed = 0
    for ud in (os.path.join(lad, "Google", "Chrome", "User Data"),
               os.path.join(lad, "Microsoft", "Edge", "User Data"),
               os.path.join(lad, "BraveSoftware", "Brave-Browser", "User Data")):
        if not os.path.isdir(ud):
            continue
        for prof in os.listdir(ud):
            if prof == "Default" or prof.startswith("Profile "):
                for sub in ("Cache", "Code Cache", "GPUCache"):
                    freed += wipe(os.path.join(ud, prof, sub))
    for d in glob.glob(os.path.join(lad, "Mozilla", "Firefox", "Profiles", "*", "cache2")):
        freed += wipe(d)
    return freed


def clean_recycle_thumbs():
    freed = 0
    ps("Clear-RecycleBin -Force -ErrorAction SilentlyContinue")
    ex = os.path.join(env("LOCALAPPDATA"), "Microsoft", "Windows", "Explorer")
    for f in glob.glob(os.path.join(ex, "thumbcache_*.db")) + glob.glob(os.path.join(ex, "iconcache_*.db")):
        try:
            s = os.path.getsize(f)
            os.remove(f)
            freed += s
        except Exception:
            pass
    return freed


def clean_shader():
    lad = env("LOCALAPPDATA")
    return sum(wipe(p) for p in (os.path.join(lad, "D3DSCache"), os.path.join(lad, "NVIDIA", "DXCache"),
                                 os.path.join(lad, "NVIDIA", "GLCache"), os.path.join(lad, "AMD", "DxCache")))


# ---------------- colour (gamma ramp) ----------------
def set_gamma(brightness=0.0, contrast=1.0, gamma=1.0, r=1.0, g=1.0, b=1.0):
    try:
        ramp = (ctypes.c_ushort * 256 * 3)()
        for i in range(256):
            v = (i / 255 - 0.5) * contrast + 0.5 + brightness
            v = min(max(v, 0.0), 1.0) ** (1.0 / gamma)
            for ch, m in enumerate((r, g, b)):
                ramp[ch][i] = int(min(max(v * m, 0.0), 1.0) * 65535)
        user32, gdi32 = ctypes.windll.user32, ctypes.windll.gdi32
        user32.GetDC.restype = ctypes.c_void_p
        user32.ReleaseDC.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        gdi32.SetDeviceGammaRamp.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        hdc = user32.GetDC(None)
        ok = gdi32.SetDeviceGammaRamp(hdc, ctypes.addressof(ramp))
        user32.ReleaseDC(None, hdc)
        return bool(ok)
    except Exception:
        return False


