def run_ops(ops):
    fails = 0
    for op in ops:
        kind = op[0]
        if kind == "reg":
            if not reg_set(op[1], op[2], op[3], op[4]):
                fails += 1
        elif kind == "regdel":
            reg_del(op[1], op[2])
        elif kind == "cmd":
            if run(op[1])[0] != 0:
                fails += 1
        elif kind == "power":
            if not set_high_perf():
                fails += 1
    return fails


# ---------------- GameLoop engine profile ----------------
LAYERS = r"HKCU\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers"
GPUPREF = r"HKCU\Software\Microsoft\DirectX\UserGpuPreferences"
ENGINE_INFO = {
    "opengl": "OpenGL+: purane / Intel GPU par stable. Tearing ho to V-Sync ON + FPS 60.",
    "directx": "DirectX+: GTX / RTX / AMD par best. GTX 1070 ke liye recommended.",
    "smart": "Smart: GameLoop khud engine chunta hai (pehle yehi try karein).",
}


def apply_engine(mode):
    exes = find_files(GAME_EXES)
    if not exes:
        return 0
    for e in exes:
        reg_set(GPUPREF, e, "REG_SZ", "GpuPreference=2;")
        if mode == "opengl":
            reg_set(LAYERS, e, "REG_SZ", "~ DISABLEDXMAXIMIZEDWINDOWEDMODE")
        else:
            reg_del(LAYERS, e)
    return len(exes)


