    def load_sysinfo(self):
        def work():
            cpu = ps("(Get-CimInstance Win32_Processor | Select-Object -First 1).Name")[1] or "Unknown CPU"
            gpus = ps("(Get-CimInstance Win32_VideoController).Name")[1].splitlines()
            gpu = next((g for g in gpus if re.search(r"nvidia|amd|radeon|geforce|rtx|gtx", g, re.I)), gpus[0] if gpus else "Unknown GPU")
            mem = psutil.virtual_memory()
            try:
                build = sys.getwindowsversion().build
                win = "Windows 11" if build >= 22000 else "Windows 10"
                sysd = f"{win} (build {build})\n{'Admin' if is_admin() else 'User mode'}"
            except Exception:
                sysd = "Windows"
            threads = psutil.cpu_count(logical=True)

            def f():
                self.info["SYSTEM"].config(text=sysd)
                self.info["PROCESSOR"].config(text=f"{cpu}\n{threads} threads")
                self.info["MEMORY"].config(text=f"{mem.total / 2**30:.1f} GB total")
                self.info["GRAPHICS"].config(text=gpu)
            self.ui(f)
        threading.Thread(target=work, daemon=True).start()

    def tick(self):
        try:
            vals = {"CPU": psutil.cpu_percent(), "RAM": psutil.virtual_memory().percent,
                    "DISK": psutil.disk_usage(env("SystemDrive", "C:") + "\\").percent}
            gpu = None
            m = re.match(r"(\d+)", self.gpu_text)
            if m:
                gpu = float(m.group(1))
            for n, (bar, lbl) in self.bars.items():
                if n == "GPU":
                    bar["value"] = gpu or 0
                    lbl.config(text=f"GPU  {gpu:.0f}%" if gpu is not None else "GPU  n/a")
                else:
                    bar["value"] = vals[n]
                    lbl.config(text=f"{n}  {vals[n]:.0f}%")
            self.gl_state.config(text="GameLoop: RUNNING" if self.game_on else "GameLoop: not running",
                                 fg=OK if self.game_on else TEXT)
        except Exception:
            pass
        self.after(1500, self.tick)

    def watcher(self):
        loops = 0
        was = False
        while True:
            try:
                now = game_running()
                if now and not was:
                    self.log("GameLoop detect hua.")
                    if self.cfg.get("auto_color"):
                        self.apply_saved_colors()
                if now and self.cfg.get("auto_opt"):
                    self.apply_priority(quiet=True)
                if was and not now:
                    self.log("GameLoop band hua.")
                    if self.cfg.get("revert"):
                        set_gamma()
                        self.ui(self.reset_color_sliders)
                        self.log("Colors normal kar diye.")
                was = now
                self.game_on = now
                if loops % 2 == 0:
                    rc, out = run(["nvidia-smi", "--query-gpu=utilization.gpu", "--format=csv,noheader,nounits"], timeout=5)
                    self.gpu_text = out.splitlines()[0].strip() if rc == 0 and out else "n/a"
                loops += 1
            except Exception:
                pass
            time.sleep(3)

    # ---------- ONE TAP ----------
    def one_tap(self):
        if self.busy:
            return
        self.busy = True
        self.ui(lambda: self.one_btn.config(state="disabled"))
        steps = [
            ("Power plan", lambda: set_high_perf()),
            ("Gaming tweaks", lambda: run_ops([o for k in GAMING_KEYS[1:] for o in TWEAK_MAP[k][2]])),
            ("Engine profile", self.step_engine),
            ("RAM clean", lambda: self.log(f"RAM clean: {fmt_mb(clean_ram())} free")),
            ("Temp clean", lambda: self.log(f"Temp clean: {fmt_mb(clean_temp())} saaf")),
            ("DNS flush", lambda: run(["ipconfig", "/flushdns"])),
            ("Timer", lambda: set_timer(self.cfg.get("timer", True))),
            ("Priority boost", self.step_boost),
        ]
        total = len(steps)
        try:
            self.log("One tap optimize shuru...")
            for i, (name, fn) in enumerate(steps):
                self.set_progress(i / total * 100, f"{name}...")
                try:
                    fn()
                except Exception as e:
                    self.log(f"{name} skip: {e}")
            self.set_progress(100, "OPTIMIZED. GameLoop kholein, baaki auto lag jayega.")
            self.log("One tap complete.")
        finally:
            self.busy = False
            self.ui(lambda: self.one_btn.config(state="normal"))

    def step_engine(self):
        mode = self.cfg.get("engine", "smart")
        n = apply_engine(mode)
        self.log(f"Engine profile ({mode}): {n} GameLoop exe configured." if n
                 else "GameLoop folder nahi mila (engine profile skip).")

    def step_boost(self):
        n = self.apply_priority()
        self.log(f"{n} GameLoop process High priority." if n else
                 "GameLoop abhi band hai. Kholte hi auto boost lag jayega.")

    def apply_priority(self, quiet=False):
        n = 0
        cpus = psutil.cpu_count(logical=True) or 1
        cores = list(range(2, cpus)) if (self.cfg.get("pin") and cpus >= 8) else None
        for p in psutil.process_iter(["name"]):
            try:
                if (p.info["name"] or "").lower() in GAME_PROCS:
                    n += 1
                    if p.nice() != psutil.HIGH_PRIORITY_CLASS:
                        p.nice(psutil.HIGH_PRIORITY_CLASS)
                        try:
                            p.ionice(psutil.IOPRIO_HIGH)
                        except Exception:
                            pass
                        if cores:
                            try:
                                p.cpu_affinity(cores)
                            except Exception:
                                pass
                        if quiet:
                            self.log(f"Auto boost: {p.info['name']} -> High")
            except Exception:
                pass
        return n

