    def force_close(self):
        n = 0
        for p in psutil.process_iter(["name"]):
            try:
                if (p.info["name"] or "").lower() in GAME_PROCS:
                    p.kill()
                    n += 1
            except Exception:
                pass
        self.log(f"{n} GameLoop process band kiye." if n else "GameLoop chal nahi raha.")

    def launch_gameloop(self):
        found = find_files(["AppMarket.exe"])
        if not found:
            self.log("GameLoop launcher nahi mila. Desktop icon se kholein.")
            return
        os.startfile(sorted(found)[0])
        self.log("GameLoop launch ho raha hai.")

    def refresh_procs(self):
        rows = []
        for p in psutil.process_iter(["pid", "name", "memory_info"]):
            try:
                rows.append((p.info["memory_info"].rss, p.info["pid"], p.info["name"] or "?"))
            except Exception:
                pass
        self.rows = sorted(rows, reverse=True)[:30]
        self.lst.delete(0, "end")
        for rss, pid, name in self.rows:
            self.lst.insert("end", f"{name:<34}{rss / 2**20:>8.0f} MB   (pid {pid})")

    def kill_selected(self):
        sel = self.lst.curselection()
        if not sel:
            return
        rss, pid, name = self.rows[sel[0]]
        if name.lower() in PROTECTED or name.lower() in GAME_PROCS:
            messagebox.showinfo(APP, f"{name} protected hai (system / game).")
            return
        if messagebox.askyesno(APP, f"{name} band karein? Unsaved kaam chala jayega."):
            try:
                psutil.Process(pid).terminate()
                self.log(f"{name} band kiya.")
            except Exception as e:
                self.log(f"Band nahi hua: {e}")
            self.refresh_procs()

